import { pgTable, text, timestamp, integer, jsonb, boolean } from "drizzle-orm/pg-core";

// Таблица для хранения профилей игроков
export const players = pgTable("players", {
  telegramId: text("telegram_id").primaryKey(),
  username: text("username"),
  firstName: text("first_name"),
  createdAt: timestamp("created_at").defaultNow().notNull(),
  updatedAt: timestamp("updated_at").defaultNow().notNull(),
});

// Таблица для хранения уровней ролей каждого игрока
export const playerRoles = pgTable("player_roles", {
  id: text("id").primaryKey(),
  telegramId: text("telegram_id").notNull().references(() => players.telegramId),
  roleId: text("role_id").notNull(),
  level: integer("level").default(1).notNull(),
  experience: integer("experience").default(0).notNull(),
  timesPlayed: integer("times_played").default(0).notNull(),
  lastPlayedAt: timestamp("last_played_at"),
  createdAt: timestamp("created_at").defaultNow().notNull(),
  updatedAt: timestamp("updated_at").defaultNow().notNull(),
});

// Таблица для хранения текущего прогресса в квесте
export const questProgress = pgTable("quest_progress", {
  id: text("id").primaryKey(),
  telegramId: text("telegram_id").notNull().references(() => players.telegramId),
  roleId: text("role_id").notNull(),
  level: integer("level").notNull(),
  currentStep: integer("current_step").default(0).notNull(),
  choices: jsonb("choices").default([]).notNull(), // Массив выборов игрока
  startedAt: timestamp("started_at").defaultNow().notNull(),
  lastActionAt: timestamp("last_action_at").defaultNow().notNull(),
  completed: boolean("completed").default(false).notNull(),
  reminderSent: boolean("reminder_sent").default(false).notNull(),
});

// Таблица для хранения истории прохождений
export const questHistory = pgTable("quest_history", {
  id: text("id").primaryKey(),
  telegramId: text("telegram_id").notNull().references(() => players.telegramId),
  roleId: text("role_id").notNull(),
  level: integer("level").notNull(),
  choices: jsonb("choices").notNull(),
  experienceGained: integer("experience_gained").notNull(),
  completedAt: timestamp("completed_at").defaultNow().notNull(),
});

// Таблица для планирования напоминаний
export const reminders = pgTable("reminders", {
  id: text("id").primaryKey(),
  telegramId: text("telegram_id").notNull().references(() => players.telegramId),
  questProgressId: text("quest_progress_id").notNull().references(() => questProgress.id),
  scheduledFor: timestamp("scheduled_for").notNull(),
  sent: boolean("sent").default(false).notNull(),
  createdAt: timestamp("created_at").defaultNow().notNull(),
});
